theme.css:
/* theme: Breach Protocol | A night of red alarms and cash drains, where a trillion-dollar wound bleeds through every ticker and span. */
/* mood: bad */
/* layout: hero=classic; political-news=outline/stack; financial-news=stat/feature; entertainment-news=tile/grid-2; sports=numbered/grid-2; music-releases=plain/stack; stock-analysis=banner/grid-3; outlook=timeline/stack */

.diary-page {
  --paper: #1c0b0d;
  --paper-alt: #241114;
  --ink: #f6eef0;
  --ink-soft: #e3d4d8;
  --muted: #c9a8ad;
  --accent: #ff4d2e;
  --accent-ink: #1a0c0e;
  --rule: #4d2a2f;
  --font-display: var(--ff-space-grotesk), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 3px solid var(--accent);
  box-shadow: inset 0 -12px 24px -12px rgba(255, 77, 46, 0.25);
}

.diary-page .diary-kicker {
  letter-spacing: 0.28em;
  font-weight: 700;
  text-shadow: 0 0 12px rgba(255, 77, 46, 0.4);
}

.diary-page .diary-title {
  font-weight: 700;
  letter-spacing: -0.04em;
  text-transform: uppercase;
  font-size: clamp(2.5rem, 7vw, 5.5rem);
  background: linear-gradient(180deg, var(--ink) 60%, var(--accent) 60%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
}

.diary-page .diary-summary {
  border-left: 4px solid var(--accent);
  padding-left: 1.25rem;
  font-weight: 400;
  font-size: clamp(1.2rem, 2.2vw, 1.5rem);
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-ui);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  border-radius: 0;
}

.diary-page .diary-theme-note {
  font-family: var(--font-ui);
  text-transform: uppercase;
  font-size: 0.8rem;
  letter-spacing: 0.08em;
}

.diary-page .diary-toc {
  border-bottom: 2px solid var(--accent);
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-toc-link.is-active {
  color: var(--accent);
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-section-number {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  font-size: clamp(1.8rem, 3.4vw, 2.6rem);
}

.diary-page .diary-section-head {
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.75rem;
}

.diary-page .diary-prose {
  font-size: 1.12rem;
  line-height: 1.7;
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-card--outline .diary-card-inner {
  border: 1px solid var(--rule);
  border-left: 4px solid var(--accent);
  border-radius: 0;
  padding: 1.5rem;
  background: rgba(255, 77, 46, 0.03);
}

.diary-page .diary-card--stat .diary-card-inner {
  border-top: 3px solid var(--accent);
  position: relative;
  overflow: hidden;
}

.diary-page .diary-card--stat .diary-card-figure {
  font-size: clamp(3rem, 14cqi, 5rem);
  text-shadow: 0 0 24px rgba(255, 77, 46, 0.3);
}

.diary-page .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
  position: relative;
  overflow: hidden;
}

.diary-page .diary-card--tile .diary-card-inner::after {
  content: "//";
  position: absolute;
  right: -0.25rem;
  bottom: -0.75rem;
  font-family: var(--ff-plex-mono), monospace;
  font-size: 4rem;
  font-weight: 600;
  color: var(--accent);
  opacity: 0.15;
  line-height: 1;
}

.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--accent);
  text-shadow: 0 0 12px rgba(255, 77, 46, 0.35);
}

.diary-page .diary-card--banner .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  position: relative;
}

.diary-page .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-display);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 0.9rem 1.25rem;
}

.diary-page .diary-card--banner .diary-card-body {
  padding: 1.25rem;
  background: rgba(255, 77, 46, 0.02);
}

.diary-page .diary-card--timeline .diary-card-inner {
  padding-left: 1.75rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  background: var(--accent);
  width: 2px;
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper), 0 0 8px rgba(255, 77, 46, 0.5);
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
  text-transform: uppercase;
  font-size: 0.7rem;
  letter-spacing: 0.08em;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: -0.01em;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-left: 3px solid var(--accent);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-markets-label {
  color: var(--muted);
  letter-spacing: 0.18em;
}

.diary-page .diary-footer {
  border-top: 3px solid var(--accent);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-card--banner .diary-card-thread {
  margin-left: 1.25rem;
  margin-right: 1.25rem;
  background: transparent;
}

.diary-page .diary-card--banner .diary-card-thread:hover {
  background: var(--accent);
}

.diary-page .diary-card--plain {
  position: relative;
}

.diary-page .diary-card--plain::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: linear-gradient(180deg, var(--accent), transparent 80%);
  opacity: 0.4;
}

.diary-page .diary-card--plain .diary-card-inner {
  padding-left: 1.5rem;
}

.diary-page .diary-stories--feature > .diary-card:first-child .diary-card-inner {
  border-bottom: 2px solid var(--accent);
  padding-bottom: 1.5rem;
}

.diary-page .diary-card--stat .diary-card-inner::before {
  content: "⚠";
  position: absolute;
  right: 1rem;
  top: 1rem;
  font-size: 1.4rem;
  color: var(--accent);
  opacity: 0.6;
}

.diary-page .diary-card--tile .diary-card-title {
  color: var(--ink);
}

.diary-page .diary-card--numbered .diary-card-inner {
  gap: 0.5rem 1rem;
}

.diary-page .diary-card-lede {
  border-left-color: var(--accent);
  font-family: var(--font-display);
  letter-spacing: -0.01em;
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

@media (prefers-reduced-motion: no-preference) {
  .diary-page .diary-card--stat .diary-card-inner {
    transition: transform 200ms ease;
  }

  .diary-page .diary-card--stat .diary-card-inner:hover {
    transform: translateY(-2px);
  }
}
